// Initialize start node
start_node_->g_value = 0.0;
start_node_->h_value = calc_h_value(start_node_);
open_list_.push_back(start_node_);

// Main A* search loop
while (!open_list_.empty())
{
    // Get the node in open list with lowest f_score (g + h)
    RouteModel::Node* current_node = next_node();

    // If we've reached the end node, we're done
    if (current_node == end_node_)
    {
        distance_ = current_node->g_value;
        return construct_final_path(current_node);
    }

    // Mark current node as visited
    current_node->visited = true;

    // Add all neighbors to open list
    add_neighbors(current_node);
}

// If we get here, no path was found
return std::vector<RouteModel::Node>();

